import { openModal } from './dialog-service.js';
import ThinkDialog from '@/mobile/components/dialog/mobile-think-dialog.vue';

/**
 * 显示Think弹窗
 * @param {Object} options 配置选项
 * @param {Function} options.onConfirm 用户确认的回调
 * @param {Function} options.onCancel 用户取消的回调
 */
export function showThinkDialog(options = {}) {
  const {
    onConfirm = null,
    onCancel = null,
    ...otherOptions
  } = options;

  const dialogProps = {
    onConfirm,
    onCancel,
    ...otherOptions
  };

  openModal(ThinkDialog, dialogProps);
} 