<template>
  <BaseModal :zIndex="zIndex" :onClose="onClose" :maskClosable="true">
    <div class="dialog-container">
      <div class="deep-search-dialog">
        <!-- 顶部指示器 -->
        <div class="home-indicator-top"></div>
        
        <!-- 头部区域 -->
        <div class="search-dialog-header">
          <h3>{{ t('searchResults') }}</h3>
            <mobile-l-img src="/static/images/close_icon.png" w="24px" h="24px" />
        </div>
        
        <!-- 内容区域 -->
        <div class="search-dialog-content" ref="contentRef">
          <div v-if="citations.length === 0" class="empty-state">
            <mobile-l-img src="/static/images/conversation/search_icon.png" w="48px" h="48px" class="empty-icon" />
            <p>{{ t('noSearchReferences') }}</p>
          </div>
          <div v-else class="citations-container">
            <div class="citations-list">
              <div 
                @click="handleCitationClick(citation)" 
                v-for="(citation, index) in citations" 
                :key="index" 
                class="citation-link-card"
              >
                <div class="citation-favicon-container">
                  <div class="favicon-border">
                    <mobile-l-img
                      :src="getFaviconUrl(citation, index)"
                      w='18px'
                      h='18px'
                      radius='6px'
                      class="favicon-icon"
                      @error="handleFaviconError(index)"
                    />
                  </div>
                </div>
                <div class="citation-text-content">
                  <div class="citation-domain-link">
                    {{ getDomain(citation) }}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
        
        <!-- 底部安全区域 -->
        <div class="bottom-safe-area"></div>
      </div>
    </div>
  </BaseModal>
</template>

<script setup>
// 引入区域
import BaseModal from '@/components/dialog/open-dialog.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import { ref, onMounted, onUnmounted } from 'vue';
import { t } from '@/language';
// 引入网站图标工具函数
import { FaviconManager, getDomainFromUrl } from '@/utils/util.js';


// props区域
const props = defineProps({
  citations: {
    type: Array,
    default: () => []
  },
  zIndex: {
    type: Number,
    default: 3000
  },
  onClose: {
    type: Function,
    required: true
  },
});

// 变量区域
const contentRef = ref(null);
// 网站图标管理器
const faviconManager = new FaviconManager();

// 点击事件区域
const handleClose = () => {
  faviconManager.reset(); // 重置图标管理器状态
  if (props.onClose) {
    props.onClose();
  }
};

const handleCitationClick = (citation) => {
  // 打开外部链接
  window.open(citation, '_blank');
};

// 业务逻辑区域
const getFaviconUrl = (url, index) => {
  return faviconManager.getFaviconUrl(url, index);
};

const handleFaviconError = (index) => {
  const url = props.citations[index];
  if (url) {
    faviconManager.handleFaviconError(index, url);
  }
};

const getDomain = (url) => {
  return getDomainFromUrl(url);
};

// 周期函数区域
onMounted(() => {
  // 弹窗打开时，重置图标管理器
  faviconManager.reset();
});

onUnmounted(() => {
  // 清理资源
  faviconManager.reset();
});
</script>

