<template>
  <BaseModal :zIndex="zIndex" :onClose="onMaskClick" :maskClosable="true">
      <div class="think-dialog" :style="{height:height}">
        <div class="think-content">
          <div class="think-content-header">
            <div class="home-indicator-top"></div>
          </div>
          <!-- 拖拽检测层 -->
          <div 
            class="drag-detection-layer"
            @touchstart="onTouchStart"
          ></div>
          <div 
            class="content-area"
            @touchstart="onContentTouchStart"
            @scroll="onContentScroll"
            :class="{ 'is-dragging': isDragging }"
          >
            <div class="dialog-title">
              <span v-if="status == 'start'">{{ t('thinking') }}...</span>
              <span v-if="status == 'end'">{{ t('thoughts') }}</span>
            </div>
            <div class="dialog-content">
              <span>{{ thinkingProcess }}</span>
              <span>{{ thinkingProcess }}</span>
              <span>{{ thinkingProcess }}</span>
              <span>{{ thinkingProcess }}</span>
            </div>
          </div>
        </div>
      </div>
  </BaseModal>
</template>

<script setup>
// 引入区域
import { ref, onMounted, onUnmounted } from 'vue';
import {t} from "@/language"
import pxToRem from '@/utils/px-to-rem';
import BaseModal from '@/components/dialog/open-dialog.vue';
// props区域
const props = defineProps({
  zIndex: { type: Number, default: 3000 },
  onClose: { type: Function, required: true },
  onConfirm: { type: Function, default: null },
  onCancel: { type: Function, default: null },
  status: { type: String, default: 'start' },
  thinkingProcess:{type:String,default:''},
});

// 变量区域
const dialogStates = {
  HALF: window.innerHeight * 0.4, // 半屏状态 40%
  FULL: window.innerHeight * 0.9, // 全屏状态 90%
  MIN_CLOSE: 100 // 最小关闭阈值
};

const height = ref(pxToRem(dialogStates.HALF)); // 默认半屏
const currentState = ref('HALF'); // 当前状态：HALF, FULL
const isDragging = ref(false);
const startY = ref(0);
const startHeight = ref(dialogStates.HALF);
const scrollTop = ref(0);
const canDrag = ref(false); // 是否可以拖拽
const dragStartState = ref('HALF'); // 记录拖拽开始时的状态

// 变量区域
const dialogTitle = ref('Think Dialog');

// 拖拽事件区域
const onTouchStart = (event) => {
  // 拖拽检测层的触摸事件，总是允许拖拽
  isDragging.value = true;
  canDrag.value = true;
  startY.value = event.touches[0].clientY;
  startHeight.value = parseInt(height.value.replace('rem', '')) * 16;
  dragStartState.value = currentState.value; // 记录拖拽开始时的状态
  
  // 添加全局事件监听 - iOS优化
  document.addEventListener('touchmove', onTouchMove, { passive: false });
  document.addEventListener('touchend', onTouchEnd, { passive: true });
};

const onContentTouchStart = (event) => {
  // 内容区域的触摸事件，需要判断滚动状态
  const contentArea = event.currentTarget;
  scrollTop.value = contentArea.scrollTop;
  
  startY.value = event.touches[0].clientY;
  startHeight.value = parseInt(height.value.replace('rem', '')) * 16;
  dragStartState.value = currentState.value; // 记录拖拽开始时的状态
  canDrag.value = false;
  
  // 添加全局事件监听 - iOS优化
  document.addEventListener('touchmove', onContentTouchMove, { passive: false });
  document.addEventListener('touchend', onTouchEnd, { passive: true });
};

const onContentScroll = (event) => {
  scrollTop.value = event.target.scrollTop;
};

const onTouchMove = (event) => {
  // 拖拽检测层的移动事件，直接处理拖拽
  if (!isDragging.value) return;
  
  event.preventDefault();
  
  const currentY = event.touches[0].clientY;
  const deltaY = startY.value - currentY;
  const newHeight = startHeight.value + deltaY;
  
  if (newHeight >= dialogStates.MIN_CLOSE && newHeight <= dialogStates.FULL + 50) {
    height.value = pxToRem(newHeight);
  }
};

const onContentTouchMove = (event) => {
  // 内容区域的移动事件，需要判断是否应该拖拽弹窗
  const currentY = event.touches[0].clientY;
  const deltaY = startY.value - currentY;
  const moveThreshold = 10;
  
  if (!canDrag.value && Math.abs(deltaY) > moveThreshold) {
    const contentArea = document.querySelector('.content-area');
    const isAtTop = contentArea.scrollTop === 0;
    // 新的拖拽逻辑
    if (deltaY > 0 && isAtTop) {
      // 向上滑动且内容在顶部
      if (currentState.value === 'HALF') {
        // 半屏状态：向上滑动先切换到全屏，不允许内容滚动
        canDrag.value = true;
        isDragging.value = true;
      } else if (currentState.value === 'FULL') {
        // 全屏状态：向上滑动允许内容滚动，不拖拽弹窗
        canDrag.value = false;
        isDragging.value = false;
        return; // 让内容正常滚动
      }
    } else if (deltaY < 0) {
      // 向下滑动处理
      if (currentState.value === 'FULL' && isAtTop) {
        // 全屏状态且在顶部：向下滑动先切换到半屏
        canDrag.value = true;
        isDragging.value = true;
      } else if (currentState.value === 'HALF' && isAtTop) {
        // 半屏状态且在顶部：向下滑动隐藏弹窗
        canDrag.value = true;
        isDragging.value = true;
      } else {
        // 其他情况（不在顶部）：让内容正常滚动，不拖拽弹窗
        canDrag.value = false;
        isDragging.value = false;
        return; // 让内容正常滚动
      }
    } else {
      return; // 让内容正常滚动
    }
  }
  
  // 只有在确实需要拖拽弹窗时才阻止默认行为
  if (!isDragging.value) return;
  
  // iOS优化：只在必要时阻止默认行为
  if (event.cancelable) {
    event.preventDefault();
  }
  
  const newHeight = startHeight.value + deltaY;
  
  if (newHeight >= dialogStates.MIN_CLOSE && newHeight <= dialogStates.FULL + 50) {
    height.value = pxToRem(newHeight);
  }
};

const onTouchEnd = () => {
  if (!isDragging.value) {
    canDrag.value = false;
    cleanupEventListeners();
    return;
  }
  
  isDragging.value = false;
  canDrag.value = false;
  
  // 移除全局事件监听
  cleanupEventListeners();
  
  const currentHeightPx = parseInt(height.value.replace('rem', '')) * 16;
  const halfHeight = dialogStates.HALF;
  const fullHeight = dialogStates.FULL;
  
  // 优化的状态切换逻辑
  if (currentHeightPx < dialogStates.MIN_CLOSE + 100) {
    // 下滑到很低，关闭弹窗
    props.onClose();
    return;
  }
  
  // 根据起始状态和当前高度决定最终状态
  const originalState = dragStartState.value;
  const heightDiff = currentHeightPx - (originalState === 'HALF' ? halfHeight : fullHeight);
  
  if (originalState === 'HALF') {
    // 从半屏开始
    if (heightDiff > 100) {
      // 向上拖拽超过100px，切换到全屏
      currentState.value = 'FULL';
      height.value = pxToRem(fullHeight);
    } else if (heightDiff < -50) {
      // 向下拖拽超过50px，关闭弹窗
      props.onClose();
      return;
    } else {
      // 回到半屏
      currentState.value = 'HALF';
      height.value = pxToRem(halfHeight);
    }
  } else if (originalState === 'FULL') {
    // 从全屏开始
    if (heightDiff < -100) {
      // 向下拖拽超过100px，切换到半屏
      currentState.value = 'HALF';
      height.value = pxToRem(halfHeight);
    } else {
      // 回到全屏
      currentState.value = 'FULL';
      height.value = pxToRem(fullHeight);
    }
  }
};

// 自定义事件区域
const onMaskClick = () => {
  // 点击空白处，如果是全屏状态则收起到半屏，如果是半屏状态则关闭
  props.onClose();
};

// 业务逻辑区域
const cleanupEventListeners = () => {
  document.removeEventListener('touchmove', onTouchMove);
  document.removeEventListener('touchmove', onContentTouchMove);
  document.removeEventListener('touchend', onTouchEnd);
};

// 周期函数区域
onMounted(() => {
  console.log('Think dialog mounted');
  // 初始化为半屏状态
  currentState.value = 'HALF';
  height.value = pxToRem(dialogStates.HALF);
});

onUnmounted(() => {
  // 清理事件监听器
  cleanupEventListeners();
});
</script>

