import { openModal } from './dialog-service.js';
import DeepSearchDialog from '@/mobile/components/dialog/mobile-deep-search-dialog.vue';

/**
 * 显示深度搜索结果弹窗
 * @param {Object} options 配置选项
 * @param {Array} options.citations 搜索结果引用列表
 * @param {Function} options.onClose 关闭弹窗的回调
 * @param {Function} options.onCitationClick 点击引用项的回调
 */
export function showDeepSearchDialog(options = {}) {
  const {
    citations = [],
    onClose = null,
    onCitationClick = null,
    ...otherOptions
  } = options;

  const dialogProps = {
    citations,
    onClose,
    onCitationClick,
    ...otherOptions
  };

  return openModal(DeepSearchDialog, dialogProps);
}