<template>
  <!-- 移动端搜索引用 - 显示在消息上方 -->
  <div v-if="props.search_citations && props.search_citations.length > 0" class="search-citations-container-mobile">
    <div class="search-icons-container" @click="clickMobileSearchCitations">
      <div v-for="(citationObj, index) in displayedCitations" :key="`${citationObj.originalIndex}-${citationObj.url}`"
        class="search-icon-item" :title="citationObj.url" :style="{zIndex:displayedCitations.length - index}">
        <mobile-l-img :src="getFaviconUrl(citationObj, index)" w="12px" h="12px" radius="2px" class="search-favicon"
          @error="handleFaviconError(index)" />
      </div>
      <span class="search-citations-text">{{ t('numWebPages', {count: props.search_citations.length}) }}</span>
    </div>
  </div>
  
  <div class="msg-send-container" :style="msgStyle">
    <!-- 如果消息发送失败，显示重试组件 -->
    <template v-if="props.role === MSG_ROLE_ASSISTANT && props.messageStatus === MESSAGE_STATUS.FAILED">
      <mobile-message-retry :isRetrying="props.isRetrying" @onRetry="onRetry" />
    </template>
    
    <!-- 正常消息内容 -->
    <Bubble v-else :content="props.content" maxWidth="100%" :noStyle="true" :isMarkdown="props.isMarkdown"
      :typing="props.typing" :isFog="false" :loading="props.showLoading" @finish="onFinish" ref="bubbleRef"
      :highlight="customHighlight" :class="props.role === MSG_ROLE_USER ? 'user-msg' : ''">
      
      <template #header v-if="props.role === MSG_ROLE_ASSISTANT">
        <!-- Think Header -->
        <mobile-msg-item-think 
          v-if="props.hasThinking && !isRecordList" 
          :thinkingProcess="props.thinkingProcess"
          :thinkingOfContent="props.content"  
          :status="props.thinkingStatus"
          class="message-bottom-spacing" />
          
        <div v-if="isRecordList && props.hasThinking" class="thinking-performed">
          <mobile-l-img src="/static/images/think_icon2.png" w="16px" h="16px"></mobile-l-img>
          <span>{{ t('thinkingPerformed') }}</span>
        </div>
      </template>
      
      <template #loading>
        <lottie-vue v-if="!props.hasThinking" path="/static/thinking.json" :loop="true" :autoplay="true" width="30px"
          height="30px" />
      </template>
    </Bubble>
  </div>
  
  <!-- 透传底部插槽给Bubble组件 -->
  <slot v-if="$slots.footer">
    <slot name="footer"></slot>
  </slot>
</template>

<script setup>
import { ref, computed } from "vue";
import { Bubble } from 'vue-element-plus-x'
import { MSG_ROLE_USER, MSG_ROLE_ASSISTANT, MESSAGE_STATUS } from "@/types/msg";
import LottieVue from "@/components/lottie.vue";
import MobileMsgItemThink from '@/mobile/components/business/mobile-msg-item-think.vue';
import MobileMessageRetry from '@/mobile/components/business/mobile-message-retry.vue';
import MobileLImg from "@/mobile/components/mobile-l-img.vue";
import { useI18n } from 'vue-i18n';
import hljs from 'highlight.js'; 
// 引入highlight.js主题样式
import 'highlight.js/styles/github.css';
// 引入网站图标工具函数
import { FaviconManager } from '@/utils/util.js';
// 引入px转rem工具函数
import { convertStyleObject } from '@/utils/px-to-rem';
import { showDeepSearchDialog } from '@/utils/dialogMethod/deep-search-dialog-service';

const { t } = useI18n();

const props = defineProps({
  content: {
    type: String,
    default: "",
  },
  role: {
    type: String,
    default: "user",
  },
  showLoading: {
    type: Boolean,
    default: true,
  },
  isMarkdown: {
    type: Boolean,
    default: false,
  },
  typing: {
    type: [Boolean, Object],
    default: false,
  },
  theme: {
    type: String,
    default: "default", // 可选值: "default", "text-tool"
  },
  // Think模式相关props
  hasThinking: {
    type: Boolean,
    default: false,
  },
  thinkingProcess: {
    type: String,
    default: "",
  },
  isRecordList:{
    type: Boolean,
    default: false
  },
  thinkingStatus: {
    type: String,
    default: 'end'
  },
  // 新增props - 消息状态相关
  messageStatus: {
    type: String,
    default: MESSAGE_STATUS.SUCCESS
  },
  isRetrying: {
    type: Boolean,
    default: false
  },
  search_citations: {
    type: Array,
    default: () => []
  }
});

const emit = defineEmits(["onFinish", "onRetry"]);

const bubbleRef = ref();

// 网站图标相关状态
const faviconManager = new FaviconManager();
const maxDisplayIcons = 3; // 最多展示3个图标

// 计算要展示的引用（最多3个，如果有失败的则补充后面的）
const displayedCitations = computed(() => {
    const citations = [];
    let sourceIndex = 0;
    
    while (citations.length < maxDisplayIcons && sourceIndex < props.search_citations.length) {
        const citation = props.search_citations[sourceIndex];
        
        // 如果这个图标还没有完全失败，则包含它
        if (faviconManager.shouldShowIcon(sourceIndex)) {
            citations.push({ url: citation, originalIndex: sourceIndex });
        }
        
        sourceIndex++;
    }
    
    return citations;
});

// 获取网站图标URL
const getFaviconUrl = (citationObj, displayIndex) => {
    const { url, originalIndex } = citationObj;
    return faviconManager.getFaviconUrl(url, originalIndex);
};

// 处理图标加载失败
const handleFaviconError = (displayIndex) => {
    const citationObj = displayedCitations.value[displayIndex];
    if (!citationObj) return;
    
    const { originalIndex, url } = citationObj;
    faviconManager.handleFaviconError(originalIndex, url);
};

// 移动端搜索引用点击事件
const clickMobileSearchCitations = () => {
  console.log('clickMobileSearchCitations', props.search_citations);
  showDeepSearchDialog({
    citations: props.search_citations,
    onClose: () => {
      console.log('onClose');
    },
  })
}

// 定义样式配置对象（原始px值）- 移动端优化
const styleConfigRaw = {
    "text-tool": {
        [MSG_ROLE_ASSISTANT]: {
            background: "#ffffff",
            border: "1px solid #E5E7EB",
            padding: "12px 14px", // 移动端减少内边距
            color: "#1B2432",
            textAlign: "left",
        },
        [MSG_ROLE_USER]: {
            background: "#2563EB",
            border: "1px solid #2563EB",
            padding: "12px 14px", // 移动端减少内边距
            color: "#FFFFFF",
            textAlign: "left",
        },
    },
    default: {
        [MSG_ROLE_ASSISTANT]: {
            background: "none",
            border: "none",
            padding: "0",
        },
        [MSG_ROLE_USER]: {
            background: "#FFF",
            border: "1px solid #E5E7EB",
            padding: "12px 14px", // 移动端减少内边距
        },
    },
};

// 转换px值为rem的样式配置对象
const styleConfig = computed(() => {
    const converted = {};
    for (const [theme, roles] of Object.entries(styleConfigRaw)) {
        converted[theme] = {};
        for (const [role, styles] of Object.entries(roles)) {
            converted[theme][role] = convertStyleObject(styles);
        }
    }
    return converted;
});

const msgStyle = computed(() => {
    // 获取当前主题，如果不是text-tool则使用default
    const currentTheme = props.theme === "text-tool" ? "text-tool" : "default";

    // 返回对应主题和角色的样式
    return styleConfig.value[currentTheme]?.[props.role] || {};
});

// 中断打字的方法
const onStopInterrupt = () => {
  if (bubbleRef.value) {
    bubbleRef.value.interrupt();
  }
};

const onFinish = () => {
    emit("onFinish");
};

// 重试事件处理
const onRetry = () => {
    emit("onRetry");
};

const customHighlight = (code, lang) => {
  if (lang && hljs.getLanguage(lang)) {
    // 使用highlight.js高亮代码
    const highlighted = hljs.highlight(code, { language: lang });
    return highlighted.value;
  }
  // 未识别语言时使用默认高亮
  return hljs.highlightAuto(code).value;
};

defineExpose({
    onStopInterrupt,
});
</script>

